  const valor = normalizarTexto(texto);
  if (!valor || contieneInfoClinicaPrivada(texto) || esConsultaCitaExistente(texto)) return false;
  if (/\b(cancelar|cambiar|modificar|mover|reprogramar|reservar|reserva|cita|agendar|pedir hora|horarios?|disponibilidad|huecos?|agenda)\b/.test(valor)) return false;
  if (/\b(servicios?|que ofrecen|que tratamientos tienen|que servicios tienen|direccion|telefono|horario)\b/.test(valor) && !contieneServicioComercialLead(valor)) return false;
